// AI: below section was generated by an AI
// Run after build_ui.mjs. Use the same optional Playwright/browser paths as render_models.cjs.
const { chromium } = require(process.env.GLASSLIGHT_PLAYWRIGHT || "playwright");
const { readFile } = require("node:fs/promises");
const { gunzipSync } = require("node:zlib");
const { join } = require("node:path");
const assert = require("node:assert/strict");

// Exercise the actual compressed firmware page with delayed catalogs and status changes, without device writes.
async function main() {
	const header = await readFile(join(__dirname, "dashboard_generated.h"), "utf8");
	const array = header.match(/INTER_COMMS_DASHBOARD\[\].*?\{([\s\S]*?)\};/)[1];
	const html = gunzipSync(Buffer.from(array.match(/0x[0-9a-f]{2}/g).map((byte) => parseInt(byte, 16))));
	const browser = await chromium.launch({ executablePath: process.env.GLASSLIGHT_BROWSER, headless: true });
	try {
		for (const mobile of [false, true]) {
			const context = await browser.newContext({ viewport: mobile ? { width: 390, height: 844 } : { width: 1280, height: 900 }, hasTouch: mobile });
			const page = await context.newPage();
			const errors = [], writes = [];
			let fx = 0, releaseCatalog, catalogRequested;
			const catalog = new Promise((resolve) => { releaseCatalog = resolve; });
			const requested = new Promise((resolve) => { catalogRequested = resolve; });
			page.on("pageerror", (error) => errors.push(error.message));
			await page.route("http://dashboard.test/**", async (route) => {
				const path = new URL(route.request().url()).pathname;
				if (path === "/") return route.fulfill({ contentType: "text/html", body: html });
				if (path === "/json/effects") {
					catalogRequested();
					await catalog;
					return route.fulfill({ json: ["Solid", "Blink", "Breathe", "Wipe", "Rainbow", "Rainbow Runner", "Fire 2012"] });
				}
				if (path.endsWith("/request")) return route.fulfill({ json: { id: "a".repeat(32) } });
				if (path.endsWith("/rpc")) {
					const command = route.request().postDataJSON();
					if (command.op === "lighting") {
						writes.push(command);
						fx = command.body.seg?.[0]?.fx ?? fx;
					}
					return route.fulfill({ status: 202 });
				}
				if (path.endsWith("/result")) return route.fulfill({ json: {
					ok: true, master: true, settled: true, localId: "001122334455",
					devices: [{ id: "001122334455", simulated: false, online: true, lightingKnown: true, bri: 128, on: true, col: 0xffaa00, sx: 128, ix: 128, fx }],
				} });
				if (path === "/json/live") return route.fulfill({ json: { leds: ["ffaa00"] } });
				return route.fulfill({ status: 404 });
			});
			await page.goto("http://dashboard.test/");
			await requested;
			const picker = page.locator("#effectPicker"), options = page.locator("#effectOptions");
			await picker.click();
			assert.equal(await options.isVisible(), true);
			assert.ok(await options.getByRole("option").count() > 100);
			const inputBox = await picker.boundingBox(), menuBox = await options.boundingBox();
			assert.ok(Math.abs(inputBox.width - menuBox.width) < 2);
			assert.ok(menuBox.height <= 250 && menuBox.x >= 0 && menuBox.x + menuBox.width <= (mobile ? 390 : 1280));
			assert.equal(await options.evaluate((list) => { list.scrollTop = list.scrollHeight; return list.scrollTop > 0; }), true);
			await picker.fill("rain");
			await picker.evaluate((input) => input.setSelectionRange(1, 3));
			releaseCatalog();
			await page.waitForFunction(() => document.querySelectorAll("#effectOptions [role=option]").length === 2);
			assert.equal(await picker.inputValue(), "rain");
			assert.deepEqual(await picker.evaluate((input) => [input.selectionStart, input.selectionEnd]), [1, 3]);
			fx = 1;
			await page.evaluate(() => window.glassDeviceBridge.settingsVisibility(true));
			await page.waitForFunction(() => document.getElementById("effect").value === "1");
			assert.equal(await picker.inputValue(), "rain");
			assert.deepEqual(await picker.evaluate((input) => [input.selectionStart, input.selectionEnd]), [1, 3]);
			assert.equal(await options.isVisible(), true);
			assert.equal(writes.length, 0);
			const rainbow = options.getByRole("option", { name: "Rainbow", exact: true });
			await rainbow[mobile ? "tap" : "click"]();
			await page.waitForFunction(() => document.getElementById("effect").value === "4");
			await page.waitForTimeout(500);
			assert.equal(writes.length, 1);
			assert.equal(writes[0].body.seg[0].fx, 4);
			assert.equal(await picker.inputValue(), "Rainbow");
			assert.equal(await options.isVisible(), false);
			await picker.fill("not an effect");
			assert.equal(await options.textContent(), "No matching effects");
			await picker.press("Escape");
			assert.equal(await picker.inputValue(), "Rainbow");
			assert.equal(writes.length, 1);
			await picker.fill("rain");
			await picker.press("ArrowUp");
			await picker.press("Enter");
			await page.waitForTimeout(500);
			assert.equal(writes.length, 2);
			assert.equal(writes[1].body.seg[0].fx, 5);
			await page.locator("#effectToggle").click();
			assert.equal(await options.getByRole("option").count(), 7);
			await page.locator("#effectToggle").click();
			assert.equal(await options.isVisible(), false);
			assert.deepEqual(errors, []);
			await context.close();
			console.log(`${mobile ? "Touch" : "Desktop"}: dropdown, filtering, draft/caret preservation, catalog/status refresh, selection and keyboard checks passed`);
		}
	} finally { await browser.close(); }
}
main().catch((error) => { console.error(error); process.exitCode = 1; });
// AI: end
